-- Generated by `npm run seed` from supabase/questions/*.json. Do not edit by hand.
-- Safe to run more than once: existing questions are skipped.
-- It first makes sure the database accepts all 14 subjects (the same change as migrate-subjects.sql), so it works on its own.
alter table public.questions drop constraint if exists questions_subject_check;
alter table public.questions add constraint questions_subject_check check (subject in ('eng','mat','phy','chm','bio','gov','eco','com','agr','acc','mkt','lit','irk','crk'));

on conflict (subject, body) do nothing;

-- Check: one row per subject with how many questions it now has (every subject should show 60 or more).
select subject, count(*) as questions from public.questions group by subject order by subject;
