insert into public.questions (subject, body, options, answer, explanation) values
('eng','Choose the word nearest in meaning to ''ubiquitous''','["rare","everywhere","hidden","ancient"]'::jsonb,1,'Ubiquitous means present everywhere.'),
('eng','Neither of the boys ___ present.','["were","are","was","have been"]'::jsonb,2,'''Neither'' takes a singular verb, so use ''was''.'),
('eng','Choose the opposite of ''benevolent''','["kind","malevolent","generous","gentle"]'::jsonb,1,'Malevolent means wishing harm; benevolent means kind.'),
('eng','He has lived here ___ 2015.','["for","since","from","at"]'::jsonb,1,'''Since'' goes with a point in time; ''for'' with a length of time.'),
('eng','''The wind whispered through the trees'' is an example of','["simile","irony","personification","hyperbole"]'::jsonb,2,'Giving human actions to a non-human thing is personification.'),
('eng','The plural of ''criterion'' is','["criterions","criteria","criterias","criterium"]'::jsonb,1,'Criterion comes from Greek; its plural is criteria.'),
('eng','Choose the correctly spelt word','["accomodation","accommodation","acommodation","accomodasion"]'::jsonb,1,'Accommodation has a double c and a double m.'),
('eng','She is good ___ mathematics.','["in","at","on","with"]'::jsonb,1,'We say ''good at'' a subject.'),
('eng','The synonym of ''candid'' is','["frank","secretive","rude","shy"]'::jsonb,0,'Candid means open and honest, which is frank.'),
('eng','He ___ his homework before the teacher arrived.','["finishes","has finished","had finished","will finish"]'::jsonb,2,'The past perfect shows an action finished before another past action.'),
('eng','''Break a leg'' is an example of','["a proverb","an idiom","a simile","a pun"]'::jsonb,1,'An idiom is not literal; ''break a leg'' means good luck.'),
('eng','The antonym of ''scarce'' is','["rare","plentiful","costly","small"]'::jsonb,1,'Scarce means in short supply; plentiful is the opposite.'),
('eng','Choose the word nearest in meaning to ''diligent''','["lazy","hardworking","careless","clever"]'::jsonb,1,'Diligent means careful and hardworking.'),
('eng','Choose the word opposite in meaning to ''transparent''','["clear","opaque","thin","bright"]'::jsonb,1,'Opaque means not able to be seen through; transparent means clear.'),
('eng','The committee ___ yet to reach a decision.','["have","has","are","were"]'::jsonb,1,'''Committee'' is treated as one body here, so use the singular ''has''.'),
('eng','Each of the students ___ a certificate.','["receive","were receiving","received","have received"]'::jsonb,2,'''Each'' is singular; ''received'' agrees with it and fits the past meaning.'),
('eng','She apologised ___ being late.','["for","about","at","on"]'::jsonb,0,'We apologise ''for'' something.'),
('eng','The meeting was called ___ because of the rain.','["off","out","away","down"]'::jsonb,0,'''Called off'' means cancelled.'),
('eng','Choose the correctly spelt word.','["necesary","neccessary","necessary","nesessary"]'::jsonb,2,'Necessary has one c and two s''s.'),
('eng','''He is as strong as an ox'' is an example of','["metaphor","simile","irony","pun"]'::jsonb,1,'A simile compares two things using ''as'' or ''like''.'),
('eng','''Time is a thief'' is an example of','["simile","metaphor","hyperbole","onomatopoeia"]'::jsonb,1,'A metaphor states one thing is another without ''as'' or ''like''.'),
('eng','''I have told you a million times'' is an example of','["hyperbole","litotes","irony","apostrophe"]'::jsonb,0,'Hyperbole is deliberate exaggeration for effect.'),
('eng','''Buzz'' and ''hiss'' are examples of','["alliteration","onomatopoeia","paradox","oxymoron"]'::jsonb,1,'Onomatopoeia is a word that imitates a sound.'),
('eng','The idiom ''to let the cat out of the bag'' means to','["lose a pet","reveal a secret","cause trouble","feel afraid"]'::jsonb,1,'It means to reveal a secret by accident.'),
('eng','The idiom ''a blessing in disguise'' means','["a hidden gift","something good that seemed bad at first","a religious act","a false friend"]'::jsonb,1,'It describes something that looks bad but turns out well.'),
('eng','Choose the option that best completes: ''If I ___ you, I would apologise.''','["am","was","were","be"]'::jsonb,2,'The subjunctive ''were'' is used in unreal conditions.'),
('eng','By the time we arrived, the film ___.','["already started","has already started","had already started","is already starting"]'::jsonb,2,'The past perfect shows an action completed before another past action.'),
('eng','He insisted ___ paying the bill.','["in","on","for","at"]'::jsonb,1,'We insist ''on'' doing something.'),
('eng','The plural of ''phenomenon'' is','["phenomenons","phenomena","phenomenas","phenomenes"]'::jsonb,1,'Phenomenon comes from Greek; its plural is phenomena.'),
('eng','Choose the word that is a noun: ''happy'', ''happily'', ''happiness'', ''happier''','["happy","happily","happiness","happier"]'::jsonb,2,'Happiness names a state, so it is a noun.'),
('eng','Identify the adverb: ''She sang beautifully.''','["She","sang","beautifully","None of these"]'::jsonb,2,'''Beautifully'' describes how she sang, so it is an adverb.'),
('eng','A word that stands in place of a noun is a','["verb","pronoun","adjective","preposition"]'::jsonb,1,'A pronoun replaces a noun, for example ''he'' or ''they''.'),
('eng','Choose the sentence that is correct.','["Me and him went home.","He and I went home.","Him and I went home.","I and him went home."]'::jsonb,1,'''He and I'' uses the subject pronouns correctly.'),
('eng','The synonym of ''abundant'' is','["scarce","plentiful","tiny","empty"]'::jsonb,1,'Abundant means existing in large quantities.'),
('eng','The antonym of ''expand'' is','["grow","stretch","contract","spread"]'::jsonb,2,'Contract means to become smaller; expand means to become larger.'),
('eng','A person who writes poems is a','["novelist","poet","dramatist","editor"]'::jsonb,1,'A poet writes poems.'),
('eng','Which of these is a compound sentence?','["I ran.","I ran, and she walked.","Running fast, I won.","Because I ran, I won."]'::jsonb,1,'A compound sentence joins two main clauses with a conjunction such as ''and''.'),
('eng','''The Nigerian ___ is rich in culture.'' Choose the correct word.','["peoples","people''s","peoples''","peopel"]'::jsonb,0,'''Peoples'' as a plural noun here means different nations or ethnic groups; the sentence needs the plain plural.'),
('eng','Choose the option closest in meaning to ''reluctant''','["eager","unwilling","joyful","brave"]'::jsonb,1,'Reluctant means unwilling or hesitant.'),
('eng','Choose the word opposite in meaning to ''frugal''','["thrifty","careful","extravagant","poor"]'::jsonb,2,'Frugal means careful with money; extravagant means wasteful.'),
('eng','Choose the word nearest in meaning to ''meticulous''','["careful","careless","hasty","noisy"]'::jsonb,0,'Meticulous means showing great attention to detail.'),
('eng','The news about the strike ___ shocking to everyone.','["were","are","have been","was"]'::jsonb,3,'''News'' is uncountable and singular, so it takes ''was''.'),
('eng','The teacher congratulated him ___ his success.','["for","on","at","with"]'::jsonb,1,'We congratulate someone ''on'' an achievement.'),
('eng','Choose the word that has the same vowel sound as the one in ''seat''.','["bit","believe","bet","bat"]'::jsonb,1,'''Believe'' has the long ''ee'' sound, as in ''seat''.'),
('eng','Choose the word that rhymes with ''night''.','["beat","bet","bout","bite"]'::jsonb,3,'''Bite'' ends with the same sound as ''night''.'),
('eng','In which of these words is the letter ''k'' silent?','["knowledge","kitchen","bake","kept"]'::jsonb,0,'The ''k'' in ''knowledge'' is not pronounced.'),
('eng','''He passed away last night'' uses a figure of speech called','["hyperbole","simile","euphemism","pun"]'::jsonb,2,'A euphemism is a gentler way of saying something unpleasant, here ''died''.'),
('eng','''A deafening silence'' is an example of','["alliteration","simile","oxymoron","onomatopoeia"]'::jsonb,2,'An oxymoron joins two contradictory words.'),
('eng','''The fat frog fled fast'' is an example of','["metaphor","alliteration","irony","personification"]'::jsonb,1,'Repeating the same initial consonant sound is alliteration.'),
('eng','The idiom ''to bury the hatchet'' means to','["start a fight","hide a weapon","dig a grave","make peace"]'::jsonb,3,'It means to end a quarrel and become friends again.'),
('eng','The idiom ''to kick the bucket'' means to','["die","fail","quit a job","play football"]'::jsonb,0,'It is an informal idiom meaning to die.'),
('eng','''Once in a blue moon'' means','["every month","very rarely","at night","suddenly"]'::jsonb,1,'The idiom describes something that happens very seldom.'),
('eng','She ___ in Lagos for ten years before she moved to Abuja.','["has lived","lives","had lived","is living"]'::jsonb,2,'The past perfect fits an action completed before another past action.'),
('eng','I ___ the news when the phone rang.','["watch","have watched","am watching","was watching"]'::jsonb,3,'The past continuous shows an action in progress when another one interrupted.'),
('eng','The number of applicants ___ increased this year.','["has","have","are","were"]'::jsonb,0,'''The number of'' takes a singular verb, so ''has''.'),
('eng','Neither the principal nor the teachers ___ aware of the change.','["was","is","has been","were"]'::jsonb,3,'The verb agrees with the nearer subject, ''teachers'', so ''were''.'),
('eng','Which of these words is correctly spelt?','["embarassment","embarrasment","embarrassment","embarrasement"]'::jsonb,2,'Embarrassment has double r and double s.'),
('eng','Pick the option with the correct spelling.','["occurence","occurrence","occurrance","ocurrence"]'::jsonb,1,'Occurrence has double c and double r.'),
('eng','''Ngozi is not as tall as her sister.'' This means that','["Ngozi''s sister is taller than Ngozi","Ngozi is taller than her sister","they are equal in height","Ngozi has no sister"]'::jsonb,0,'''Not as tall as'' means shorter, so the sister is taller.'),
('eng','''Only the manager can sign the document.'' This means that','["the manager cannot sign it","everyone but the manager can sign it","nobody except the manager can sign it","the manager signs only some documents"]'::jsonb,2,'''Only'' limits the right to sign to the manager alone.'),
('eng','Complete the question tag: ''Tola can swim, ___?''','["isn''t she","doesn''t she","can she","can''t she"]'::jsonb,3,'A positive statement takes a negative tag with the same auxiliary.'),
('eng','Choose the correctly punctuated sentence.','["Its a pity that the dog lost it''s collar.","It''s a pity that the dog lost its collar.","It''s a pity that the dog lost it''s collar.","Its'' a pity that the dog lost its collar."]'::jsonb,1,'''It''s'' is short for ''it is'', while ''its'' shows possession.'),
('eng','A place where bees are kept is called an','["apiary","aviary","aquarium","orchard"]'::jsonb,0,'An apiary is a place where bees are kept.'),
('eng','Choose the word nearest in meaning to ''obsolete''','["modern","useful","fragile","outdated"]'::jsonb,3,'Obsolete means no longer in use or out of date.'),
('eng','Choose the word opposite in meaning to ''verbose''','["wordy","concise","talkative","loud"]'::jsonb,1,'Verbose means using too many words; concise means brief.'),
('eng','The minister, together with his aides, ___ arrived.','["have","are","has","were"]'::jsonb,2,'The subject is ''minister''; ''together with his aides'' does not change the verb''s number.'),
('eng','The thief was accused ___ stealing the phone.','["of","for","with","about"]'::jsonb,0,'We accuse someone ''of'' a wrongdoing.'),
('eng','Choose the correct reported form: She said, "I am tired." becomes ''She said that she ___ tired.''','["is","were","was","has been"]'::jsonb,2,'In reported speech the present tense ''am'' changes to the past ''was''.'),
('eng','Choose the passive form of ''The cook prepared the meal.''','["The meal is prepared by the cook.","The meal had been prepared by the cook.","The cook was prepared by the meal.","The meal was prepared by the cook."]'::jsonb,3,'The simple past passive is ''was prepared by''.'),
('mat','Solve 2x + 5 = 17','["x = 5","x = 6","x = 11","x = 12"]'::jsonb,1,'2x = 17 − 5 = 12, so x = 6.'),
('mat','Evaluate log₁₀100 + log₁₀10','["2","3","10","1000"]'::jsonb,1,'log₁₀100 = 2 and log₁₀10 = 1, so the sum is 3.'),
('mat','Area of a circle of radius 7 cm (π = 22/7)','["44 cm²","154 cm²","49 cm²","22 cm²"]'::jsonb,1,'Area = πr² = 22/7 × 49 = 154.'),
('mat','If sin θ = 3/5 (θ acute), cos θ =','["3/4","4/5","5/4","4/3"]'::jsonb,1,'With sin = 3/5 the sides are 3, 4, 5, so cos = 4/5.'),
('mat','The gradient of the line y = 3x − 4 is','["−4","4","3","−3"]'::jsonb,2,'In y = mx + c the gradient is m, which is 3.'),
('mat','Sum of the interior angles of a hexagon','["540°","720°","900°","360°"]'::jsonb,1,'(n − 2) × 180 = 4 × 180 = 720°.'),
('mat','Simplify (x² − 9) / (x − 3)','["x − 3","x + 3","x² + 3","x"]'::jsonb,1,'x² − 9 = (x − 3)(x + 3), so cancel x − 3.'),
('mat','Find the value of 2³ × 2²','["10","32","64","16"]'::jsonb,1,'2³ × 2² = 2⁵ = 32.'),
('mat','The mean of 2, 4, 6 and 8 is','["4","5","6","20"]'::jsonb,1,'The sum is 20; 20 ÷ 4 = 5.'),
('mat','Express 0.25 as a percentage','["2.5%","25%","0.25%","250%"]'::jsonb,1,'Multiply by 100: 0.25 × 100 = 25%.'),
('mat','Solve x² − 5x + 6 = 0','["x = 2 or 3","x = −2 or −3","x = 1 or 6","x = 5 or 1"]'::jsonb,0,'(x − 2)(x − 3) = 0, so x = 2 or 3.'),
('mat','A right-angled triangle has shorter sides 3 cm and 4 cm. Its hypotenuse is','["5 cm","6 cm","7 cm","25 cm"]'::jsonb,0,'3² + 4² = 25, and √25 = 5.'),
('mat','Simplify 3² × 3³','["3⁶","3⁵","9⁵","27"]'::jsonb,1,'Add the powers when multiplying: 3²⁺³ = 3⁵ = 243.'),
('mat','Factorise x² − 9','["(x − 3)²","(x + 3)²","(x − 3)(x + 3)","(x − 9)(x + 1)"]'::jsonb,2,'This is a difference of two squares: a² − b² = (a − b)(a + b).'),
('mat','If y = 3x − 2, find y when x = 4','["10","14","12","6"]'::jsonb,0,'y = 3(4) − 2 = 12 − 2 = 10.'),
('mat','The sum of the interior angles of a hexagon is','["540°","720°","900°","360°"]'::jsonb,1,'(n − 2) × 180° = 4 × 180° = 720°.'),
('mat','Each exterior angle of a regular octagon is','["30°","40°","45°","60°"]'::jsonb,2,'Exterior angles add up to 360°, so 360° ÷ 8 = 45°.'),
('mat','Find the mean of 2, 4, 6, 8 and 10','["5","6","7","8"]'::jsonb,1,'Sum = 30, and 30 ÷ 5 = 6.'),
('mat','Find the median of 3, 7, 1, 9, 5','["3","5","7","9"]'::jsonb,1,'Arranged: 1, 3, 5, 7, 9. The middle value is 5.'),
('mat','Find the mode of 2, 3, 3, 4, 5, 3, 6','["2","3","4","5"]'::jsonb,1,'3 appears most often (three times).'),
('mat','A bag has 3 red and 5 blue balls. The probability of picking a red ball is','["3/5","3/8","5/8","1/3"]'::jsonb,1,'Probability = 3 red ÷ 8 balls in total = 3/8.'),
('mat','Circumference of a circle of radius 7 cm (π = 22/7)','["22 cm","44 cm","154 cm","14 cm"]'::jsonb,1,'C = 2πr = 2 × 22/7 × 7 = 44 cm.'),
('mat','The volume of a cuboid 5 cm by 4 cm by 3 cm is','["12 cm³","47 cm³","60 cm³","120 cm³"]'::jsonb,2,'V = l × w × h = 5 × 4 × 3 = 60 cm³.'),
('mat','The hypotenuse of a right-angled triangle with legs 6 cm and 8 cm is','["10 cm","12 cm","14 cm","100 cm"]'::jsonb,0,'√(6² + 8²) = √100 = 10 cm.'),
('mat','Express 0.25 as a fraction in its lowest terms','["1/2","1/4","2/5","1/5"]'::jsonb,1,'0.25 = 25/100 = 1/4.'),
('mat','Simplify 2/3 + 1/4','["3/7","11/12","3/12","1/6"]'::jsonb,1,'2/3 = 8/12 and 1/4 = 3/12, so the sum is 11/12.'),
('mat','Find 20% of 450','["70","80","90","100"]'::jsonb,2,'20/100 × 450 = 90.'),
('mat','Find the simple interest on ₦5,000 at 10% per annum for 2 years','["₦500","₦1,000","₦1,500","₦2,000"]'::jsonb,1,'I = PRT/100 = 5000 × 10 × 2 / 100 = ₦1,000.'),
('mat','Solve 3x − 7 = 11','["x = 4","x = 5","x = 6","x = 18"]'::jsonb,2,'3x = 18, so x = 6.'),
('mat','The 10th term of the AP 3, 7, 11, … is','["39","43","40","37"]'::jsonb,0,'Tₙ = a + (n − 1)d = 3 + 9 × 4 = 39.'),
('mat','The next term of the GP 2, 6, 18, … is','["24","36","54","72"]'::jsonb,2,'The common ratio is 3, so the next term is 18 × 3 = 54.'),
('mat','Evaluate log₂ 8','["2","3","4","8"]'::jsonb,1,'2³ = 8, so log₂ 8 = 3.'),
('mat','The gradient of the line joining (1, 2) and (3, 8) is','["2","3","4","6"]'::jsonb,1,'(8 − 2) ÷ (3 − 1) = 6 ÷ 2 = 3.'),
('mat','If A = {1, 2, 3, 4} and B = {3, 4, 5}, then A ∩ B is','["{1, 2, 3, 4, 5}","{3, 4}","{1, 2}","{5}"]'::jsonb,1,'The intersection holds elements found in both sets: 3 and 4.'),
('mat','How many elements are in A ∪ B, where A = {1, 2, 3, 4} and B = {3, 4, 5}?','["7","5","4","3"]'::jsonb,1,'A ∪ B = {1, 2, 3, 4, 5}, which has 5 elements.'),
('mat','Solve the inequality 2x + 1 > 7','["x > 3","x < 3","x > 4","x > 6"]'::jsonb,0,'2x > 6, so x > 3.'),
('mat','Expand (x + 2)²','["x² + 4","x² + 2x + 4","x² + 4x + 4","x² + 4x + 2"]'::jsonb,2,'(x + 2)(x + 2) = x² + 2x + 2x + 4 = x² + 4x + 4.'),
('mat','Express 4,500 in standard form','["4.5 × 10²","4.5 × 10³","4.5 × 10⁴","45 × 10³"]'::jsonb,1,'4,500 = 4.5 × 1,000 = 4.5 × 10³.'),
('mat','The area of a triangle with base 10 cm and height 6 cm is','["16 cm²","30 cm²","60 cm²","3 cm²"]'::jsonb,1,'Area = ½ × 10 × 6 = 30 cm².'),
('mat','Convert 101101 (base 2) to a number in base 10','["43","47","45","41"]'::jsonb,2,'1×32 + 0×16 + 1×8 + 1×4 + 0×2 + 1 = 45.'),
('mat','Evaluate 2 1/2 ÷ 5/6','["3","2","4","25/12"]'::jsonb,0,'5/2 × 6/5 = 3.'),
('mat','Simplify sqrt(75) − sqrt(12)','["3","3 sqrt(3)","7 sqrt(3)","sqrt(63)"]'::jsonb,1,'sqrt(75) = 5 sqrt(3) and sqrt(12) = 2 sqrt(3), so the difference is 3 sqrt(3).'),
('mat','Rationalise 6/(3 − sqrt(3))','["3 − sqrt(3)","2 + sqrt(3)","6 + 2 sqrt(3)","3 + sqrt(3)"]'::jsonb,3,'Multiply top and bottom by (3 + sqrt(3)): 6(3 + sqrt(3))/(9 − 3) = 3 + sqrt(3).'),
('mat','Given that log10 2 = 0.3010, find log10 5','["0.6990","0.6020","0.1505","0.7010"]'::jsonb,0,'log10 5 = log10(10/2) = 1 − 0.3010 = 0.6990.'),
('mat','In a class, 30 students offer Physics, 25 offer Chemistry and 45 offer at least one of the two. How many offer both?','["5","15","20","10"]'::jsonb,3,'n(P ∩ C) = 30 + 25 − 45 = 10.'),
('mat','y varies inversely as x^2. If y = 4 when x = 3, find y when x = 6','["2","1","8","16"]'::jsonb,1,'k = yx^2 = 4 × 9 = 36, so y = 36/36 = 1.'),
('mat','Z varies directly as x and inversely as y. If Z = 6 when x = 4 and y = 2, find Z when x = 8 and y = 3','["8","6","9","12"]'::jsonb,0,'Z = kx/y gives 6 = 4k/2, so k = 3; then Z = 3 × 8/3 = 8.'),
('mat','Form the quadratic equation whose roots are 2 and −1/2','["2x^2 + 3x − 2 = 0","2x^2 − 3x − 2 = 0","2x^2 − 3x + 2 = 0","2x^2 + 3x + 2 = 0"]'::jsonb,1,'(x − 2)(2x + 1) = 2x^2 − 3x − 2 = 0.'),
('mat','If 2x + 3y = 12 and x − y = 1, find the value of xy','["5","6","8","12"]'::jsonb,1,'From x = y + 1: 2y + 2 + 3y = 12, so y = 2, x = 3 and xy = 6.'),
('mat','Solve the inequality 3 − 2x < 9','["x < −3","x > 3","x < 3","x > −3"]'::jsonb,3,'−2x < 6; dividing by −2 reverses the sign, so x > −3.'),
('mat','Find the sum of the first 12 terms of the AP 5, 8, 11, …','["246","264","258","270"]'::jsonb,2,'S = n/2 [2a + (n − 1)d] = 6(10 + 33) = 258.'),
('mat','Find the sum to infinity of the GP 8, 4, 2, …','["12","15","32","16"]'::jsonb,3,'S = a/(1 − r) = 8/(1 − 1/2) = 16.'),
('mat','Find the equation of the line through (2, 3) with gradient −2','["y = −2x − 1","y = −2x + 7","y = 2x − 1","y = −2x + 1"]'::jsonb,1,'y − 3 = −2(x − 2), so y = −2x + 7.'),
('mat','Find the midpoint of the line joining (−2, 5) and (6, 1)','["(4, 6)","(−2, 3)","(2, −3)","(2, 3)"]'::jsonb,3,'((−2 + 6)/2, (5 + 1)/2) = (2, 3).'),
('mat','Evaluate tan 60° × cos 30°','["1/2","sqrt(3)/2","3","3/2"]'::jsonb,3,'sqrt(3) × sqrt(3)/2 = 3/2.'),
('mat','From a point 30 m from the foot of a tower on level ground, the angle of elevation of the top is 60°. Find the height of the tower','["30 m","10 sqrt(3) m","30 sqrt(3) m","60 m"]'::jsonb,2,'h = 30 tan 60° = 30 sqrt(3) m.'),
('mat','Find the length of the arc of a sector of radius 12 cm and angle 60°','["4π cm","2π cm","8π cm","6π cm"]'::jsonb,0,'Arc = 60/360 × 2π × 12 = 4π cm.'),
('mat','Find the volume of a cylinder of radius 7 cm and height 10 cm (π = 22/7)','["440 cm^3","770 cm^3","1540 cm^3","3080 cm^3"]'::jsonb,2,'V = πr^2h = 22/7 × 49 × 10 = 1540 cm^3.'),
('mat','The angle subtended by an arc at the centre of a circle is 100°. The angle it subtends at the circumference is','["25°","100°","200°","50°"]'::jsonb,3,'The angle at the centre is twice the angle at the circumference, so 100° ÷ 2 = 50°.'),
('mat','A trader sells an article for ₦4,500 at a profit of 25%. Find the cost price','["₦3,375","₦4,000","₦3,600","₦5,625"]'::jsonb,2,'Selling price = 125% of cost, so cost = 4500 × 100/125 = ₦3,600.'),
('mat','The mean of five numbers is 8. When a sixth number 14 is added, the new mean is','["8","9","10","11"]'::jsonb,1,'Total = 40 + 14 = 54, and 54 ÷ 6 = 9.'),
('mat','Find the standard deviation of 2, 4, 4, 4, 5, 5, 7, 9','["2","4","3","5"]'::jsonb,0,'Mean = 5; squared deviations sum to 32; variance = 32/8 = 4, so SD = 2.'),
('mat','Two fair dice are thrown. The probability that the sum of the scores is 7 is','["1/12","5/36","1/6","7/36"]'::jsonb,2,'There are 6 favourable outcomes out of 36, so 6/36 = 1/6.'),
('mat','A and B are independent events with P(A) = 0.4 and P(B) = 0.5. Find P(A or B)','["0.7","0.9","0.2","0.1"]'::jsonb,0,'P(A ∪ B) = 0.4 + 0.5 − 0.4 × 0.5 = 0.7.'),
('mat','If a = (3, −1) and b = (1, 2), find 2a − b','["(5, −4)","(7, 0)","(5, 0)","(−5, 4)"]'::jsonb,0,'2a = (6, −2); subtracting b gives (6 − 1, −2 − 2) = (5, −4).'),
('mat','If y = 3x^3 − 5x^2 + 2x − 1, find dy/dx at x = 2','["22","14","18","30"]'::jsonb,2,'dy/dx = 9x^2 − 10x + 2; at x = 2 this is 36 − 20 + 2 = 18.'),
('mat','Evaluate the integral of (2x + 1) dx from x = 1 to x = 3','["8","10","12","14"]'::jsonb,1,'[x^2 + x] from 1 to 3 = (9 + 3) − (1 + 1) = 10.'),
('mat','Find the determinant of the matrix with rows (3, 2) and (1, 4)','["10","14","12","8"]'::jsonb,0,'3 × 4 − 2 × 1 = 10.'),
