('irk','The holy book given to Prophet Isa (AS) is the','["Injil","Tawrat","Zabur","Suhuf"]'::jsonb,0,'It is the Gospel revealed to him.'),
('irk','The compulsory prayer with two rak''ah is','["Dhuhr","Fajr","Asr","Isha"]'::jsonb,1,'Fajr is the dawn prayer.'),
('irk','The number of rak''ah in the Maghrib prayer is','["three","two","four","five"]'::jsonb,0,'It is the sunset prayer.'),
